(() => {
 'use strict';
 const root=document.querySelector('#admin-app'),auth=window.ColorWinAuth;
 const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const displayValue=v=>typeof v==='string'?v.replace(/[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}/gi,id=>idLabels[id.toLowerCase()]||'Record'):Array.isArray(v)?v.map(displayValue):v&&typeof v==='object'?Object.fromEntries(Object.entries(v).map(([k,x])=>[k,displayValue(x)])):v;
 const money=v=>'₹'+Number(v||0).toLocaleString('en-IN',{minimumFractionDigits:2,maximumFractionDigits:2});
 const date=v=>v?new Date(v).toLocaleString('en-IN',{timeZone:'Asia/Kolkata'}):'—';
 const panels={superadmin:'Superadmin',finance:'Finance',gifts_users:'Gift Codes & Users',ff:'Free Fire Tournaments',support:'All Support'};
 const defaults={superadmin:'overview',finance:'deposits',gifts_users:'users',ff:'tournaments',support:'support'};
 const menu=[['overview','Overview','◈','superadmin'],['users','Users','♙','gifts_users'],['deposits','Deposits','↓','finance'],['withdrawals','Withdrawals','↑','finance'],['ledger','Wallet ledger','₹','finance'],['support','Support appeals','◌','support'],['feedback','Feedback','✎','support'],['tournaments','Tournaments','♜','ff'],['entries','Players & rewards','★','ff'],['announcements','Announcements','◁','support'],['gifts','Gift codes & coupons','◇','gifts_users'],['games','Game controls','▦','superadmin'],['settings','Site & payment settings','⚙','superadmin'],['panel-keys','Panel keys','⌘','superadmin'],['history','Admin changes history','≡','superadmin']];
 const panelForSection=Object.fromEntries(menu.map(([id,,,scope])=>[id,scope]));
 let idLabels={},matchFilter='',matchTitle='';
 let role='',panelScope='superadmin',section='overview',page=0,search='',rows=[],total=0,revision=0;
 const allowed=scope=>panelScope===scope;
 function route(){
  const hash=location.hash;
  if(!hash||hash==='#')return {panel:'superadmin',section:'overview'};
  const key=hash.replace(/^#\/?/,'');
  if(!key||key.includes('/'))return null;
  if(panels[key])return {panel:key,section:defaults[key]};
  if(panelForSection[key])return {panel:panelForSection[key],section:key};
  return null;
 }
 let tokenReady=false;
 let financeRefreshBusy=false;
 async function refreshFinance(){
  const body=document.querySelector('#admin-body');
  const editing=document.activeElement?.matches?.('input,textarea,select,[contenteditable="true"]');
  if(financeRefreshBusy||!tokenReady||!auth.session||!allowed('finance')||!['deposits','withdrawals'].includes(section)||document.hidden||!body||body.querySelector('.loading')||document.querySelector('dialog[open]')||editing)return;
  const requested={revision,section,page,search,user:auth.session.user.id};financeRefreshBusy=true;
  try{
   const data=await rpc('colorwin_admin_list',{p_section:requested.section,p_search:requested.search,p_page:requested.page});
   if(!tokenReady||requested.revision!==revision||requested.section!==section||requested.page!==page||requested.search!==search||auth.session?.user?.id!==requested.user||!body.isConnected||document.hidden||document.querySelector('dialog[open]')||document.activeElement?.matches?.('input,textarea,select,[contenteditable="true"]'))return;
   const nextRows=data.rows||[],nextTotal=Number(data.total||0),nextLabels=data.id_labels||{};
   if(JSON.stringify([nextRows,nextTotal,nextLabels])===JSON.stringify([rows,total,idLabels]))return;
   rows=nextRows;total=nextTotal;idLabels=nextLabels;table(body);
  }catch{/* Keep the visible records; the next poll retries without interrupting a review. */}
  finally{financeRefreshBusy=false;}
 }
 const rpc=async(name,args)=>{try{return await auth.accountRpc(name,args);}catch(err){if(String(err.message).includes('ADMIN_TOKEN_REQUIRED')){tokenReady=false;role='';revision++;document.querySelectorAll('dialog').forEach(d=>d.close());enter();}throw err;}};
 const tokenRpc=async(action,token=null,current=null,totp=null)=>{const result=await rpc('colorwin_admin_token',{p_action:action,p_token:token,p_current:current,p_totp:totp,p_panel:panelScope});if(result.ok===false)throw Error(result.error);return result;};
 const tokenFields=()=>field('key','Panel access key','','password','required minlength="16" maxlength="256" autocomplete="off"');

 async function signOut(){if(['finance','superadmin'].includes(panelScope))await window.ColorWinAdminPush?.disable?.();tokenReady=false;role='';revision++;document.querySelectorAll('dialog').forEach(d=>d.close());await auth.logout();login();}
 function tokenGate(state,error=''){tokenReady=false;role='';const title=panels[panelScope]||'Admin';const unconfigured=!state.configured;root.innerHTML=`<section class="login"><img src="assets/web%20images/color-win-logo-supplied.png" alt="Color Win"><h1>Unlock ${esc(title)} panel</h1><p>Enter this panel's private access key. Keys are separate for every panel and are never placed in the URL.</p>${unconfigured?`<p class="error">This panel key has not been generated. Open <a href="#superadmin">Superadmin</a> and use Panel keys to create it.</p>`:''}${error?'<p class="error">'+esc(error)+'</p>':''}${state.configured?`<form id="admin-token">${tokenFields()}${button('Unlock panel')}<p class="error" role="alert"></p></form>`:''}<p>Your key is checked on the server; only an opaque, temporary session is stored in this browser.</p></section>`;const f=document.querySelector('#admin-token');if(f){f.onsubmit=async e=>{e.preventDefault();if(!f.reportValidity())return;const b=f.querySelector('[type=submit]');b.disabled=true;try{await tokenRpc('unlock',f.elements.key.value);f.reset();await enter();}catch(err){f.querySelector('.error').textContent=err.message;}finally{b.disabled=false;}};}}

 function notice(text,error=false){const el=document.querySelector('#admin-notice');el.textContent=text;el.className=error?'error':'success';el.style.display='block';clearTimeout(notice.timer);notice.timer=setTimeout(()=>el.style.display='none',6000);}
 const field=(name,label,value='',type='text',extra='')=>`<label>${esc(label)}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;
 const area=(name,label,value='',extra='')=>`<label class="full">${esc(label)}<textarea name="${name}" ${extra}>${esc(value)}</textarea></label>`;
 const select=(name,label,options,value)=>`<label>${esc(label)}<select name="${name}">${options.map(o=>`<option value="${esc(o)}" ${o===value?'selected':''}>${esc(({ff:'Free Fire',pubg:'PUBG · coming soon',draft:'Draft · not published',open:'Open for registration',live:'Match is live',completed:'Match completed',cancelled:'Cancelled',approve_deposit:'Approve verified deposit',reject_deposit:'Reject deposit',process_withdrawal:'Start processing',pay_withdrawal:'Mark paid',reject_withdrawal:'Reject & refund','assets/tournaments/free-fire-50x-red-prizes.png':'Red · Free Fire','assets/tournaments/free-fire-10x-green-prizes.png':'Green · Free Fire','assets/tournaments/free-fire-100x-purple-prizes.png':'Neon · Free Fire','assets/tournaments/master-banner.png':'Color Win master banner'})[o]||o)}</option>`).join('')}</select></label>`;
 const check=(name,label,value=false)=>`<label class="check"><input name="${name}" type="checkbox" ${value?'checked':''}>${esc(label)}</label>`;
 const button=label=>`<button type="submit" class="primary">${label}</button>`;
 const status=v=>`<span class="status ${/^[a-z]+$/.test(v)?v:''}">${esc(v||'—')}</span>`;
 const actionNames={approve_deposit:'Deposit approved',reject_deposit:'Deposit rejected',process_withdrawal:'Withdrawal processing started',pay_withdrawal:'Withdrawal marked paid',reject_withdrawal:'Withdrawal rejected & refunded',user_update:'User details updated',wallet_adjustment:'Wallet balance adjusted',support_update:'Customer appeal updated',feedback_update:'Feedback updated',save_tournament:'Tournament saved',tournament_result:'Match result & reward published',save_settings:'Site settings changed',announcement:'Announcement saved',campaign:'Promotion campaign saved',gift_create:'Gift code created',game_control:'Game availability changed',admin_access:'Admin access changed',admin_key_unlock:'Admin panel opened',admin_key_rotate:'Access key changed',admin_token_setup:'Access token created',admin_token_rotate:'Access token changed',admin_token_set:'Access token set'};
 const pretty=v=>String(v||'').replaceAll('_',' ').replace(/\b\w/g,c=>c.toUpperCase());
 function changesHistory(body){body.innerHTML=`<div class="history-intro"><div><h2>Admin changes history</h2><p>See what changed, when it changed and the reason. Latest changes appear first.</p></div><span>${total} saved changes</span></div><div class="changes-list">${rows.length?rows.map((r,i)=>`<article class="change-card"><div class="change-marker">${r.action?.includes('key')||r.action?.includes('token')?'⌘':'✓'}</div><div><time>${esc(date(r.created_at))} · IST</time><h3>${esc(actionNames[r.action]||pretty(r.action))}</h3><p>${esc((r.reason||'No note provided').replace(/^\[Key session [a-f0-9]+\]\s*/,''))}</p><small>${r.reason?.startsWith('[Key session')||r.action?.startsWith('admin_key')?'Owner access key':'Authorized admin'} · Record ${esc(displayValue(r.target||'panel'))}</small></div><button data-change="${i}">See changes</button></article>`).join(''):'<div class="empty"><h2>No changes yet</h2><p>Saved admin changes will appear here automatically.</p></div>'}</div><div class="pagination"><button id="history-prev" ${page===0?'disabled':''}>Previous</button><span>Page ${page+1}</span><button id="history-next" ${(page+1)*50>=total?'disabled':''}>Next</button></div>`;body.querySelector('#history-prev').onclick=()=>{page--;load();};body.querySelector('#history-next').onclick=()=>{page++;load();};body.querySelectorAll('[data-change]').forEach(b=>b.onclick=()=>{const r=rows[Number(b.dataset.change)],d=modal(actionNames[r.action]||pretty(r.action)),before=r.before_data||{},after=r.after_data||{},keys=[...new Set([...Object.keys(before),...Object.keys(after)])].filter(k=>JSON.stringify(before[k])!==JSON.stringify(after[k])),value=v=>v===undefined||v===null?'—':typeof v==='object'?JSON.stringify(displayValue(v),null,2):String(displayValue(v));d.querySelector('.record-actions').innerHTML=`<p class="history-note">${esc(date(r.created_at))} · IST<br>${esc((r.reason||'').replace(/^\[Key session [a-f0-9]+\]\s*/,''))}</p>${keys.length?`<div class="change-details">${keys.map(k=>`<section><h3>${esc(pretty(k))}</h3><div><article><small>Before</small><pre>${esc(value(before[k]))}</pre></article><article><small>After</small><pre>${esc(value(after[k]))}</pre></article></div></section>`).join('')}</div>`:'<p>This entry records an admin access event. No record fields were changed.</p>'}`;});}
 function notFound(){tokenReady=false;role='';root.innerHTML='<section class="admin-not-found"><div><span>404</span><h1>Page Not Found</h1><p>This admin route does not exist.</p></div></section>';}
 function login(error=''){const target=route();if(!target){notFound();return;}panelScope=target.panel;tokenGate({configured:true},error);}
 async function enter(){const rev=++revision;if(!auth.ready)return;const target=route();if(!target){notFound();return;}panelScope=target.panel;section=target.section;try{const access=await tokenRpc('status');if(rev!==revision)return;if(!access.unlocked){tokenGate(access);return;}if((access.panel||panelScope)!==panelScope){await auth.logout();if(rev!==revision)return;const locked=await tokenRpc('status');if(rev!==revision)return;tokenGate(locked);return;}tokenReady=true;role=access.role||'owner';shell();await load();}catch(err){if(rev===revision)login(err.message);}}
 function shell(){const target=route();panelScope=target.panel;section=target.section;if(!menu.some(x=>x[0]===section&&allowed(x[3])))section=defaults[panelScope];const title=menu.find(x=>x[0]===section)?.[1]||panels[panelScope],panelTitle=panels[panelScope].toUpperCase();root.innerHTML=`<div class="layout"><aside class="sidebar" id="admin-sidebar" aria-label="Admin navigation"><button class="mobile-nav-close" type="button" aria-label="Close menu">×</button><a class="brand" href="#${panelScope}"><img src="assets/web%20images/color-win-logo-supplied.png" alt="Color Win"><span>${esc(panelTitle.endsWith('PANEL')?panelTitle:panelTitle+' PANEL')}</span></a><nav>${menu.filter(x=>allowed(x[3])).map(([id,label,icon])=>`<a href="#${id}" class="${id===section?'current':''}"><span>${icon}</span>${label}</a>`).join('')}</nav><footer>Panel-specific key access<br>Actions are checked on the server<br><a href="/">Open user website ↗</a></footer></aside><button class="admin-menu-backdrop" type="button" aria-label="Dismiss navigation"></button><section class="admin-main"><header class="admin-top"><button class="mobile-menu" type="button" aria-label="Open menu" aria-controls="admin-sidebar" aria-expanded="false">☰</button><div><h1>${esc(title)}</h1><small>${esc(panelTitle)} · COLOR WIN</small></div><div>${['finance','superadmin'].includes(panelScope)?'<button id="admin-phone-notifications" type="button">Notifications</button>':''}<button id="admin-refresh">Refresh</button><button id="admin-logout">Sign out</button></div></header><div class="admin-body" id="admin-body"><p class="loading">Loading records…</p></div></section></div>`;
  const layout=document.querySelector('.layout'),menuButton=document.querySelector('.mobile-menu');const toggleMenu=open=>{layout.classList.toggle('menu-open',open);menuButton.setAttribute('aria-expanded',String(open));if(open)document.querySelector('.sidebar nav a')?.focus();else menuButton.focus();};menuButton.onclick=()=>toggleMenu(!layout.classList.contains('menu-open'));document.querySelector('.admin-menu-backdrop').onclick=()=>toggleMenu(false);document.querySelector('.mobile-nav-close').onclick=()=>toggleMenu(false);root.onkeydown=e=>{if(e.key==='Escape'&&layout.classList.contains('menu-open'))toggleMenu(false);};document.querySelector('#admin-refresh').onclick=()=>load();document.querySelector('#admin-logout').onclick=()=>signOut().catch(err=>notice(err.message,true));window.ColorWinAdminPush?.bind();
 }
 async function load(){const rev=++revision,body=document.querySelector('#admin-body');if(!body)return;body.innerHTML='<p class="loading">Loading records…</p>';try{if(section==='panel-keys'){const data=await rpc('colorwin_admin_panel_keys',{p_action:'list'});if(rev===revision&&body.isConnected)panelKeys(body,data.panels||[]);return;}const data=await rpc('colorwin_admin_list',{p_section:section==='history'?'audit':section,p_search:section==='entries'?(matchFilter||search):search,p_page:page});if(rev!==revision||!body.isConnected)return;idLabels=data.id_labels||{};rows=data.rows||[];total=Number(data.total||0);if(section==='overview')overview(body,data);else if(section==='tournaments')window.ColorWinAdminTournaments.render(body,rows,{esc,money,date,field,area,modal,page,total,reload:load,changePage:delta=>{page+=delta;load();},players:r=>{matchFilter=r.id;matchTitle=r.title;location.hash='#entries';},remove:async r=>{await rpc('colorwin_admin_action',{p_action:'delete_tournament',p_data:{id:r.id},p_reason:'Completed tournament deleted'});notice('Tournament removed. Player and wallet history preserved.');},save:async data=>{await rpc('colorwin_admin_action',{p_action:'save_tournament',p_data:data,p_reason:actionNames.save_tournament});notice(data.status==='open'?'Tournament published':data.status==='live'?'Match started':'Tournament saved');}});else if(section==='settings')settings(body);else if(section==='history')changesHistory(body);else table(body); }catch(err){if(rev===revision&&body.isConnected)body.innerHTML=`<div class="data-error">${esc(err.message)}<p>Use Refresh to retry. No action was submitted.</p></div>`;}}
 function overview(body,d){const launchers=Object.entries(panels).filter(([id])=>id!=='superadmin');const cards=[['Registered users',d.users,'users'],['UTRs to verify',d.pending_deposits,'finance'],['Withdrawals to review',d.pending_withdrawals,'finance'],['Open appeals',d.pending_support,'support'],['Wallet liabilities',money(d.wallet_total),'finance'],['Verified deposits',money(d.deposits_total),'finance'],['Paid withdrawals',money(d.withdrawals_total),'finance']];body.innerHTML=`<p class="intro">Superadmin overview. Each operations panel opens with its own separate access key.</p><div class="stats">${cards.map(([label,value,id])=>`<article class="stat"><span>${label}</span><strong>${esc(value)}</strong><a href="#${id}">Open panel →</a></article>`).join('')}</div><div class="panel-launchers">${launchers.map(([id,label])=>`<a class="panel-launcher" href="#${id}"><h2>${esc(label)}</h2><span>Open ${esc(label)} panel →</span></a>`).join('')}</div>`;}
 function panelKeys(body,items,revealed=null){body.innerHTML=`<p class="intro">Create one independent key for each panel. Keys are generated on the server, stored only as password hashes, and shown only once. Rotating a key immediately revokes the previous key's sessions.</p><div class="table-wrap"><table><thead><tr><th>Panel</th><th>Status</th><th>Last changed</th><th>Action</th></tr></thead><tbody>${items.map(item=>`<tr><td data-label="Panel">${esc(item.label)}</td><td data-label="Status">${status(item.configured?'configured':'not configured')}</td><td data-label="Last changed">${date(item.updated_at)}</td><td data-label="Action"><button type="button" data-panel-key="${esc(item.panel)}">${item.configured?'Rotate key':'Generate key'}</button></td></tr>`).join('')}</tbody></table></div><div id="panel-key-reveal"></div>`;body.querySelectorAll('[data-panel-key]').forEach(button=>button.onclick=async()=>{const item=items.find(entry=>entry.panel===button.dataset.panelKey);if(item?.configured&&typeof window.confirm==='function'&&!window.confirm(`Rotate the ${item.label} key? The old key will stop working immediately.`))return;button.disabled=true;try{const result=await rpc('colorwin_admin_panel_keys',{p_action:'provision',p_panel:button.dataset.panelKey});const current=await rpc('colorwin_admin_panel_keys',{p_action:'list'});panelKeys(body,current.panels||[],{label:item.label,key:result.key});}catch(err){notice(err.message,true);}finally{button.disabled=false;}});if(revealed){const box=body.querySelector('#panel-key-reveal');box.className='callout';box.innerHTML=`<h2>${esc(revealed.label)} key — copy it now</h2><p>This key cannot be recovered later. Store it privately; never put it in a link or source file.</p><label>New panel key<input type="text" readonly value="${esc(revealed.key)}"></label><button type="button" data-copy-panel-key>Copy key</button><button type="button" data-dismiss-panel-key>Dismiss</button>`;box.querySelector('[data-copy-panel-key]').onclick=async()=>{try{await navigator.clipboard.writeText(revealed.key);notice('Panel key copied. Store it securely.');}catch{notice('Clipboard unavailable. Select and copy the key manually.',true);}};box.querySelector('[data-dismiss-panel-key]').onclick=()=>box.replaceChildren();}}
 const renderBasePanelKeys=panelKeys;
 panelKeys=(body,items,revealed=null)=>{renderBasePanelKeys(body,items,revealed);renderSuperadminSecurity(body);};
 function renderSuperadminSecurity(body){
  const host=document.createElement('section');host.id='superadmin-key-security';host.className='panel wide';host.innerHTML='<h2>Superadmin key & authenticator</h2><p>Loading authenticator status…</p>';body.append(host);
  const showError=(message,retry)=>{host.innerHTML=`<h2>Superadmin key & authenticator</h2><p class="error" role="alert">${esc(message)}</p><button type="button" data-totp-retry>Retry</button>`;host.querySelector('[data-totp-retry]').onclick=retry;};
  const status=async()=>{host.innerHTML='<h2>Superadmin key & authenticator</h2><p>Loading authenticator status…</p>';try{const result=await auth.accountRpc('colorwin_admin_totp',{p_action:'status'});if(host.isConnected)showStatus(result);}catch(error){if(host.isConnected)showError(error.message,status);}};
  const enrollmentForm=pending=>{host.innerHTML=`<h2>Protect Superadmin key rotation</h2><p>Set up Google Authenticator or another TOTP app. Your current Superadmin key is required to begin setup.</p><form id="totp-enroll-form"><label>Current Superadmin key<input name="current_key" type="password" minlength="16" maxlength="256" autocomplete="current-password" required></label><button class="primary" type="submit">${pending?'Continue authenticator setup':'Set up authenticator'}</button><p class="error" role="alert"></p></form>`;host.querySelector('#totp-enroll-form').onsubmit=async event=>{event.preventDefault();const form=event.currentTarget;if(!form.reportValidity())return;const button=form.querySelector('[type=submit]'),action=pending?'resume':'enroll';button.disabled=true;try{const result=await auth.accountRpc('colorwin_admin_totp',{p_action:action,p_current_key:form.elements.current_key.value});if(host.isConnected)showEnrollment(result);}catch(error){form.querySelector('.error').textContent=error.message;}finally{button.disabled=false;}};};
  const showEnrollment=result=>{host.innerHTML=`<h2>Scan with your authenticator app</h2><p>Scan this QR code in Google Authenticator, then enter the current six-digit code to finish setup. The secret is shown once here for manual entry. Store it privately.</p><div class="admin-totp-setup"><div id="admin-totp-qr" aria-label="Authenticator setup QR code"></div><div><strong>Setup key</strong><code class="admin-totp-secret">${esc(result.secret)}</code></div></div><form id="totp-confirm-form"><label>Authenticator code<input name="code" type="text" inputmode="numeric" autocomplete="one-time-code" pattern="[0-9]{6}" minlength="6" maxlength="6" required></label><button class="primary" type="submit">Verify and enable</button><p class="error" role="alert"></p></form>`;const qr=host.querySelector('#admin-totp-qr');if(window.QRCode){try{new window.QRCode(qr,{text:result.uri,width:190,height:190,colorDark:'#171322',colorLight:'#ffffff',correctLevel:window.QRCode.CorrectLevel.M});}catch{qr.textContent='QR unavailable. Enter the setup key manually in your authenticator app.';}}else qr.textContent='Enter the setup key manually in your authenticator app.';host.querySelector('#totp-confirm-form').onsubmit=async event=>{event.preventDefault();const form=event.currentTarget;if(!form.reportValidity())return;const button=form.querySelector('[type=submit]');button.disabled=true;try{await auth.accountRpc('colorwin_admin_totp',{p_action:'confirm',p_code:form.elements.code.value});notice('Authenticator enabled. Superadmin key rotation now requires its code.');status();}catch(error){form.querySelector('.error').textContent=error.message;}finally{button.disabled=false;}};};
  const showRotation=()=>{host.innerHTML='<h2>Rotate Superadmin key</h2><p>Enter your current key, choose a new unique key of at least 32 characters, and confirm the current authenticator code. Other admin sessions are revoked when the key changes.</p><form id="superadmin-rotate-form"><label>Current Superadmin key<input name="current" type="password" minlength="16" maxlength="256" autocomplete="current-password" required></label><label>New Superadmin key<input name="token" type="password" minlength="32" maxlength="256" autocomplete="new-password" required></label><label>Confirm new key<input name="confirm" type="password" minlength="32" maxlength="256" autocomplete="new-password" required></label><label>Google Authenticator code<input name="totp" type="text" inputmode="numeric" autocomplete="one-time-code" pattern="[0-9]{6}" minlength="6" maxlength="6" required></label><button class="primary" type="submit">Verify and rotate key</button><p class="error" role="alert"></p></form><p class="muted">Do not reuse a key shared in chat. Save the new key in a password manager; it cannot be recovered.</p>';host.querySelector('#superadmin-rotate-form').onsubmit=async event=>{event.preventDefault();const form=event.currentTarget;if(!form.reportValidity())return;const error=form.querySelector('.error');if(form.elements.token.value!==form.elements.confirm.value){error.textContent='The new key and confirmation do not match.';return;}if(form.elements.token.value===form.elements.current.value){error.textContent='The new key must differ from the current key.';return;}const button=form.querySelector('[type=submit]');button.disabled=true;error.textContent='';try{await tokenRpc('rotate',form.elements.token.value,form.elements.current.value,form.elements.totp.value);form.reset();notice('Superadmin key rotated. Store the new key securely.');}catch(err){error.textContent=err.message;}finally{button.disabled=false;}};};
  function showStatus(result){if(result.enabled){showRotation();return;}enrollmentForm(Boolean(result.pending));}
  status();
 }
 const columnMap={users:['Member','Phone','Wallet','Inviter','Status','Joined'],deposits:['Order / UTR','Member','Amount','Receiver','Status','Created'],withdrawals:['Request','Member','Amount','Beneficiary','Status','Created'],support:['Appeal','Member','Category','Status','Updated'],feedback:['Message','Member','Status','Created'],ledger:['Reference','Member','Amount','Source','Created'],tournaments:['Tournament','Game / mode','Fee / prize','Status','Starts'],entries:['Match / game UID','Member','Rank','Reward','Status','Created'],promotion:['Campaign','Active','Created'],announcements:['Announcement','Active','Created'],gifts:['Code','Kind / amount','Claims','Expires'],games:['Game','Enabled','Updated'],admins:['Member','Phone','Role','Active'],audit:['Action / actor','Target','Reason','Created']};
 function cells(r){const member=`${esc(r.display_name||(r.public_uid?'UID '+r.public_uid:'—'))}<small>UID ${esc(r.public_uid||'—')} · ${esc(r.phone||'—')}</small>`;switch(section){
 case 'users':return [`${esc(r.display_name)}<small>UID ${r.public_uid}</small>`,esc(r.phone),money(r.balance),esc(r.inviter_uid?'UID '+r.inviter_uid:'—'),status(r.is_blocked?'suspended':'active'),date(r.created_at)];
 case 'deposits':return [`${esc(r.number)}<small>UTR ${esc(r.utr||'Not submitted')}</small>`,member,money(r.amount),esc(r.recipient_upi),status(r.status),date(r.created_at)];
 case 'withdrawals':return [esc(r.number),member,money(r.amount),`${esc(r.payout_snapshot.kind)}<small>${esc(r.payout_snapshot.details.account)}</small>`,status(r.status),date(r.created_at)];
 case 'support':return [esc(r.number),member,esc(r.category),status(r.status),date(r.updated_at)];
 case 'feedback':return [esc(r.message.slice(0,90)),member,status(r.status),date(r.created_at)];
 case 'ledger':return [esc(displayValue(r.reference)),member,money(r.amount),esc(r.source),date(r.created_at)];
 case 'tournaments':return [esc(r.title),esc(r.game.toUpperCase()+' / '+r.mode),money(r.entry_fee)+' / '+money(r.prize_pool),status(r.status),date(r.starts_at)];
 case 'entries':return [`${esc(displayValue(r.tournament_id))}<small>Game UID ${esc(r.player_id)} · ${esc(r.player_name)}</small>`,member,esc(r.rank||'—'),money(r.reward)+'<small>Most kills: '+money(r.most_kills_reward||0)+'</small>',status(r.reward_paid_at?'played':r.status),date(r.created_at)];
 case 'promotion':return [esc(r.title),status(r.active?'active':'disabled'),date(r.created_at)];
 case 'announcements':return [esc(r.title),status(r.active?'active':'hidden'),date(r.created_at)];
 case 'gifts':return [esc(r.code),esc(r.kind)+' / '+money(r.amount),`${r.claims} / ${r.max_claims}`,date(r.expires_at)];
 case 'games':return [esc(r.game_id),status(r.enabled?'enabled':'disabled'),date(r.updated_at)];
 case 'admins':return [`${esc(r.display_name)}<small>UID ${esc(r.public_uid||'—')}</small>`,esc(r.phone),esc(r.role),status(r.active?'active':'revoked')];
 case 'audit':return [`${esc(r.action)}<small>${esc(displayValue(r.actor))}</small>`,esc(r.target),esc(r.reason),date(r.created_at)];default:return [];}}
 function table(body){const create=['tournaments','announcements','gifts','admins','games'].includes(section);body.innerHTML=`<div class="toolbar"><form id="admin-search"><input type="search" name="search" value="${esc(search)}" placeholder="Search phone, UID, status, reference…" aria-label="Search records"><button type="submit">Search</button></form>${create?'<button class="primary" id="admin-create">+ Create / configure</button>':''}</div><div class="table-wrap">${rows.length?`<table><thead><tr>${columnMap[section].map(x=>'<th>'+x+'</th>').join('')}<th>Review</th></tr></thead><tbody>${rows.map((r,i)=>`<tr>${cells(r).map((x,j)=>`<td data-label="${esc(columnMap[section][j])}" class="${j===0?'title':''}"><div class="admin-cell-value">${x}</div></td>`).join('')}<td data-label="Review" class="admin-review-cell"><button data-record="${i}">View ${['audit','ledger','gifts'].includes(section)?'record':'/ manage'}</button></td></tr>`).join('')}</tbody></table>`:`<div class="empty"><h2>No ${esc(section)} records found</h2><p>${search?'Try another search.':'New records will appear here as users submit requests.'}</p></div>`}</div><div class="pagination"><button id="admin-prev" ${page===0?'disabled':''}>Previous</button><span>Page ${page+1} · ${total} records</span><button id="admin-next" ${(page+1)*50>=total?'disabled':''}>Next</button></div>`;
  body.querySelector('#admin-search').onsubmit=e=>{e.preventDefault();search=e.currentTarget.elements.search.value.trim();page=0;load();};body.querySelector('#admin-prev').onclick=()=>{page--;load();};body.querySelector('#admin-next').onclick=()=>{page++;load();};body.querySelector('#admin-create')?.addEventListener('click',()=>edit({}));body.querySelectorAll('[data-record]').forEach(b=>{b.onclick=()=>edit(rows[Number(b.dataset.record)]);});if(section==='entries'&&matchFilter){body.querySelector('#admin-search').remove();const header=document.createElement('div');header.className='callout';header.innerHTML='<strong>Players: '+esc(matchTitle)+'</strong> <button type="button">View all players</button>';header.querySelector('button').onclick=()=>{matchFilter='';matchTitle='';page=0;load();};body.prepend(header);}}
 function modal(title,r={}){const d=document.createElement('dialog');d.innerHTML=`<div class="dialog-heading"><h2>${esc(title)}</h2><button type="button" data-close aria-label="Close">×</button></div>${Object.keys(r).length?`<dl class="record">${Object.entries(r).map(([k,v])=>`<dt>${esc(({user_id:'Player',inviter_id:'Inviter',public_uid:'Color Win UID',inviter_uid:'Inviter UID',actor:'Admin',reviewed_by:'Reviewed by',tournament_id:'Tournament'})[k]||k.replaceAll('_',' '))}</dt><dd>${typeof v==='object'&&v!==null?'<pre>'+esc(JSON.stringify(displayValue(v),null,2))+'</pre>':esc(displayValue(v??'—'))}</dd>`).join('')}</dl>`:''}<div class="attachments"></div><div class="record-actions"></div>`;document.body.append(d);d.querySelector('[data-close]').onclick=()=>d.close();d.onclose=()=>d.remove();d.showModal();return d;}
 async function copyPayment(value){if(navigator.clipboard?.writeText){await navigator.clipboard.writeText(value);return;}const input=document.createElement('textarea');input.value=value;input.style.cssText='position:fixed;opacity:0;left:0;top:0';(document.querySelector('dialog[open]')||document.body).append(input);try{input.focus();input.select();if(!document.execCommand('copy'))throw Error('Copy unavailable');}finally{input.remove();}}
 function paymentModal(title,r){const d=modal(title),withdraw=section==='withdrawals',p=r.payout_snapshot||{},details=p.details||{},kind=p.kind;const fields=[['Order number',r.number,true],['Color Win UID',r.public_uid,true],['Player',r.display_name],['Phone',r.phone,true],['Amount',money(r.amount)],['Status',pretty(r.status)],['Created',date(r.created_at)]];
  if(withdraw){fields.push(['Pay via',kind==='bank'?'Bank transfer':kind==='upi'?'UPI':kind||'Unavailable'],['Account holder',details.name||details.alias]);if(kind==='upi')fields.push(['UPI ID',details.account,true]);else if(kind==='bank')fields.push(['Bank',details.bank],['Account number',details.account,true],['IFSC',details.ifsc,true]);if(r.payout_reference)fields.push(['Payout UTR',r.payout_reference,true]);}
  else fields.push(['Payment method',String(r.method||'').toUpperCase()],['Submitted UTR',r.utr,true],['Receiver UPI',r.recipient_upi,true],['Receiver name',r.recipient_name]);
  const record=document.createElement('dl');record.className='record payment-record';record.innerHTML=fields.map(([label,value,copy])=>`<dt>${esc(label)}</dt><dd><span>${esc(value??'—')}</span>${copy&&value?`<button type="button" data-payment-copy="${esc(value)}" aria-label="Copy ${esc(label)}">Copy</button>`:''}</dd>`).join('');d.querySelector('.attachments').before(record);record.querySelectorAll('[data-payment-copy]').forEach(b=>b.onclick=async()=>{try{await copyPayment(b.dataset.paymentCopy);b.textContent='Copied';}catch{notice('Copy unavailable. Select the value and copy it.');}});return d;}
 function attachForm(d,action,fields,label,transform=x=>x,initial={}){const box=d.querySelector('.record-actions');box.innerHTML=`<form><div class="form-grid">${fields}</div>${button(label)}<p class="error" role="alert"></p></form>`;window.ColorWinAdminDate.bind(box.querySelector('form'));window.ColorWinAdminDate.bind(box.querySelector('form'));box.querySelector('form').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget;if(!f.reportValidity())return;const raw={...initial,...Object.fromEntries(new FormData(f))};f.querySelectorAll('input[type=checkbox]').forEach(x=>raw[x.name]=x.checked);const b=f.querySelector('[type=submit]');b.disabled=true;try{const data=transform(raw),actionId=typeof action==='function'?action(raw):action,why=actionNames[actionId]||pretty(actionId);delete data.reason;const result=await rpc('colorwin_admin_action',{p_action:actionId,p_data:data,p_reason:why});d.close();notice('Saved. Change saved in Admin changes history.');await load();if(section==='gifts'&&result.code)modal('Gift code created',result);}catch(err){f.querySelector('.error').textContent=err.message;b.disabled=false;}};}
 function tournamentFields(r){return field('title','Tournament name',r.title||'','text','required minlength="3" maxlength="100"')+select('game','Game',['ff','pubg'],r.game||'ff')+select('mode','Team format',['Solo','Duo','Squad'],r.mode||'Solo')+select('status','Tournament status',['draft','open','live','completed','cancelled'],r.status||'draft')+select('banner','Banner',['assets/tournaments/free-fire-50x-red-prizes.png','assets/tournaments/free-fire-10x-green-prizes.png','assets/tournaments/free-fire-100x-purple-prizes.png','assets/tournaments/master-banner.png'],r.banner||'assets/tournaments/free-fire-50x-red-prizes.png')+field('entry_fee','Entry fee INR',r.entry_fee||0,'number','required min="0" step="0.01"')+field('prize_pool','Total reward budget INR',r.prize_pool||0,'number','required min="0" step="0.01"')+field('capacity','Player / team slots',r.capacity||48,'number','required min="1" max="1000"')+window.ColorWinAdminDate.render('starts_at','Match date & time',r.starts_at)+field('room_link','Room invite link (HTTPS)',r.room_link||'','url','maxlength="2000" placeholder="Paste Free Fire room invite link"')+field('room_id','Room ID (blank keeps existing)',r.room_id||'','text','maxlength="100"')+field('room_password','Room password (set with room ID)',r.room_password||'','text','maxlength="100"')+area('rules','Rules, team requirements & scoring',r.rules||'','maxlength="5000"');}
 function rewardSections(d,r,prizeRank){
 const box=d.querySelector('.record-actions');box.innerHTML='<p>Match result and Most kills are separate rewards. The same player can receive both. Their combined amount must fit the tournament reward budget.</p>';
 if(!r.reward_paid_at&&!r.most_kills_paid_at){const area=document.createElement('section');area.className='callout';box.append(area);area.innerHTML='<h3>First + second reward together</h3><div class="reward-form"></div>';const host=area.querySelector('.reward-form');attachForm({querySelector:()=>host,close:()=>d.close()},'tournament_both_rewards',field('cw_uid','Color Win UID receiving both rewards',r.public_uid,'text','readonly')+field('first_reward','First reward · Match win INR','','number','required min="0.01" step="0.01"')+field('second_reward','Second reward · Most kills INR','','number','required min="0.01" step="0.01"')+check('verified','I verified both rewards for this player'),'Give both rewards',x=>{if(!x.verified)throw Error('Verify both rewards first');delete x.verified;return x;},{id:r.id});}
 for(const kind of ['winner','kills']){const area=document.createElement('section');area.className='callout';box.append(area);const paid=kind==='winner'?r.reward_paid_at:r.most_kills_paid_at;area.innerHTML='<h3>'+(kind==='winner'?'First reward · Match win':'Second reward · Most kills')+'</h3><div class="reward-form"></div>';const host=area.querySelector('.reward-form');
 if(paid){host.innerHTML='<p>Already credited: '+money(kind==='winner'?r.reward:r.most_kills_reward)+'</p>';continue;}
 const facade={querySelector:()=>host,close:()=>d.close()};
 attachForm(facade,kind==='winner'?'tournament_result':'tournament_most_kills',field('ff_uid','Free Fire UID',r.player_id,'text','readonly')+field('cw_uid','Color Win UID receiving reward',r.public_uid,'text','readonly')+(kind==='winner'?field('rank','Final rank',typeof prizeRank==='number'?prizeRank||'':'','number','required min="1"'):'')+field('reward',kind==='winner'?'Match reward INR':'Most kills reward INR',0,'number','required min="0.01" step="0.01"')+check('verified','I verified this reward against the match result'),kind==='winner'?'Give first reward':'Give second reward',x=>{if(!x.verified)throw Error('Verify result first');delete x.verified;return x;},{id:r.id});
 }
 }
 async function edit(r,prizeRank=0){const d=['deposits','withdrawals'].includes(section)?paymentModal(menu.find(x=>x[0]===section)[1],r):modal(menu.find(x=>x[0]===section)[1],r),id=r.id;if(section==='deposits'&&r.status==='pending')attachForm(d,x=>x.decision,select('decision','Decision',['approve_deposit','reject_deposit'],'reject_deposit')+field('bank_reference','Enter deposit UTR','','text','maxlength="100"')+check('verified','I checked this amount, receiver and UTR against the bank statement'), 'Save reviewed decision',x=>{if(x.decision==='approve_deposit'&&!x.verified)throw Error('Verify the bank statement before approving.');delete x.verified;return x;},{id});
 else if(section==='withdrawals'&&['pending','processing'].includes(r.status))attachForm(d,x=>x.decision,select('decision','Decision',[...(r.status==='pending'?['process_withdrawal']:[]),'pay_withdrawal','reject_withdrawal'],'reject_withdrawal')+field('payout_reference','Enter your UTR','','text','maxlength="100"')+check('paid','I completed the external bank / UPI transfer'), 'Save reviewed decision',x=>{if(x.decision==='pay_withdrawal'&&!x.paid)throw Error('Complete and verify the actual payout first.');delete x.paid;return x;},{id});
 else if(section==='users'&&allowed('gifts_users'))attachForm(d,'user_update',field('display_name','Display name',r.display_name,'text','required minlength="2" maxlength="30"')+check('is_blocked','Suspend this user',r.is_blocked),'Update user',x=>x,{id});
 else if(section==='support'&&!['resolved','rejected'].includes(r.status)){attachForm(d,'support_update',select('status','Decision',['reviewing','resolved','rejected'],'reviewing')+area('reply','Reply visible to customer',r.admin_reply,'required minlength="3" maxlength="2000"')+check('apply_change','Apply verified IFSC / bank-name correction or deactivate the requested beneficiary'),'Update appeal',x=>x,{id});}
 else if(section==='feedback')attachForm(d,'feedback_update',select('status','Status',['reviewed','resolved'],r.status==='resolved'?'resolved':'reviewed'),'Update feedback',x=>x,{id});
 else if(section==='tournaments')attachForm(d,'save_tournament',tournamentFields(r),'Save tournament',x=>({...x,starts_at:window.ColorWinAdminDate.toIso(x.starts_at)}),id?{id}:{});
 else if(section==='entries'&&r.status!=='cancelled')rewardSections(d,r,prizeRank);
 else if(section==='announcements')attachForm(d,'announcement',field('title','Title',r.title||'','text','required minlength="3" maxlength="100"')+area('message','Message',r.message||'','required minlength="3" maxlength="5000"')+check('active','Publish announcement',r.active!==false),'Save announcement',x=>x,id?{id}:{});
 else if(section==='gifts'&&!r.code)attachForm(d,'gift_create',select('kind','Gift type',['cash','coupon'],'cash')+field('amount','Gift amount INR',100,'number','required min="0.01" max="100000" step="0.01"')+field('minimum_deposit','Coupon minimum deposit INR',0,'number','required min="0" step="0.01"')+field('max_claims','Maximum claims',1,'number','required min="1" max="100000"')+window.ColorWinAdminDate.render('expires_at','Gift expiry date & time','',true),'Create gift code',x=>({...x,expires_at:window.ColorWinAdminDate.toIso(x.expires_at)}));
 else if(section==='admins')attachForm(d,'admin_access',field('public_uid','Color Win player UID',r.public_uid||'','text','required inputmode="numeric" pattern="[0-9]+"')+select('role','Role',['owner','finance','support','tournaments','content'],r.role||'support')+check('active','Enable admin access',r.active!==false),'Save admin access');
 else if(section==='games')attachForm(d,'game_control',select('game_id','Game',(window.ColorWinGamesData?.gamesCatalog||[]).map(x=>x.id),r.game_id)+check('enabled','Enable game',r.enabled!==false),'Save game control');
 if(section==='users'&&allowed('gifts_users')){const extra=document.createElement('button');extra.type='button';extra.className='danger';extra.textContent='Audited wallet adjustment';d.querySelector('.record-actions').append(extra);extra.onclick=()=>{const w=modal('Wallet adjustment',{user_id:r.id,phone:r.phone,balance:r.balance});attachForm(w,'wallet_adjustment',field('amount','Signed INR amount (negative = debit)',0,'number','required min="-100000" max="100000" step="0.01"'),'Record adjustment',x=>x,{user_id:r.id,request_id:crypto.randomUUID()});};}
 if(section==='support')for(const a of r.attachments||[]){const b=document.createElement('button');b.type='button';b.textContent='Open '+(a.label||'attachment');d.querySelector('.attachments').append(b);b.onclick=async()=>{b.disabled=true;try{const url=await auth.supportUrl(a.path);window.open(url,'_blank','noopener,noreferrer');}catch(err){notice(err.message,true);}finally{b.disabled=false;}};}
 }
 function settings(body){body.innerHTML='<p class="intro">Settings are saved on the server and applied to the user website. Financial limits require owner access.</p><div class="forms-grid"></div>';for(const r of rows){if(r.key==='payments'&&!allowed('superadmin'))continue;const v=r.value;const p=document.createElement('section');p.className='panel';p.innerHTML=`<h2>${esc(r.key.toUpperCase())}</h2><form>${r.key==='payments'?field('receiverName','Receiver display name',v.receiverName,'text','required')+area('upiIds','Receiver UPI IDs (one per line)',(v.upiIds||[]).join('\n'),'required')+field('minDeposit','Minimum deposit',v.minDeposit,'number','required min="1"')+field('maxDeposit','Maximum deposit',v.maxDeposit,'number','required min="1"')+field('minWithdraw','Minimum withdrawal',v.minWithdraw,'number','required min="1"')+field('maxWithdraw','Maximum withdrawal',v.maxWithdraw,'number','required min="1"')+check('enabled','Enable deposits & withdrawals',v.enabled):r.key==='site'?check('maintenance','Maintenance mode',v.maintenance)+check('supportEnabled','Enable new support appeals',v.supportEnabled)+check('tournamentsEnabled','Enable tournament registrations',v.tournamentsEnabled):check('enabled','Enable promotion section',v.enabled)+field('telegram','Official Telegram URL',v.telegram||'','url')} ${button('Save settings')}<p class="error" role="alert"></p></form>`;body.querySelector('.forms-grid').append(p);p.querySelector('form').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,b=f.querySelector('[type=submit]'),values=Object.fromEntries(new FormData(f)),why='Updated '+r.key+' settings';f.querySelectorAll('[type=checkbox]').forEach(x=>values[x.name]=x.checked);if(r.key==='payments'){values.upiIds=values.upiIds.split(/\r?\n/).map(x=>x.trim()).filter(Boolean);for(const k of ['minDeposit','maxDeposit','minWithdraw','maxWithdraw'])values[k]=Number(values[k]);}b.disabled=true;try{await rpc('colorwin_admin_action',{p_action:'save_settings',p_data:{key:r.key,value:values},p_reason:why});notice('Settings updated');}catch(err){f.querySelector('.error').textContent=err.message;}finally{b.disabled=false;}};}}
 window.addEventListener('hashchange',()=>{page=0;search='';if(location.hash!=='#entries'){matchFilter='';matchTitle='';}enter();});auth.init(()=>{if(auth.ready)enter();});
 setInterval(async()=>{if(!role||!tokenReady||!auth.session)return;try{const state=await tokenRpc('status');if(!state.unlocked){revision++;document.querySelectorAll('dialog').forEach(d=>d.close());tokenGate(state);}}catch(err){tokenReady=false;role='';revision++;document.querySelectorAll('dialog').forEach(d=>d.close());login(err.message);}},30000);
 setInterval(refreshFinance,3000);
 window.addEventListener('focus',refreshFinance);
 document.addEventListener('visibilitychange',()=>{if(!document.hidden)void refreshFinance();});
 document.addEventListener('close',()=>void refreshFinance(),true);
 window.ColorWinAdminHelpers={escape:esc,menu,refreshFinance};
})();
